import os
import boto3

def synthesize_ssml(payload, config=None):
    config = config or {}
    client = boto3.client("polly", region_name=config.get("region", "us-east-1"))
    params = {
        "Text": payload,
        "TextType": "ssml",
        "OutputFormat": config.get("output_format", "mp3"),
        "VoiceId": config.get("voice_id", "Joanna"),
    }
    if "language_code" in config:
        params["LanguageCode"] = config["language_code"]
    result = client.synthesize_speech(**params)["AudioStream"].read()
    return result
